const RoomGrid = ({ rooms }) => {
  return (
    <div className="room-grid">
      {rooms.map((room) => (
        <div 
          key={room.roomNumber} 
          className={`room ${room.booked ? "booked" : ""}`} // Ensure "booked" class is applied
        >
          {room.roomNumber}
        </div>
      ))}
    </div>
  );
};
